.control
  * DC Operating Point for Power
  op
  let power = -i(VDD) * 1.8
  print power

  * AC Analysis for Gain, Bandwidth, and Phase Margin
  ac dec 100 1 1G
  let gain_db = vdb(Vout)
  let phase_deg = 180/PI * cph(v(Vout))

  meas ac aol_dc find gain_db at=10
  meas ac f_un when gain_db=0 fall=1
  meas ac phase_at_fun find phase_deg when gain_db=0 fall=1

  * Calculate Phase Margin (assuming phase starts at 0 and drops)
  let pm = phase_at_fun + 180
  print pm

  quit
.endc

